async function updateImages() {
  const ebayIds = Object.keys(imagesMap)
  console.log(`📸 Mise à jour des images pour ${ebayIds.length} produits...`)
  
  let success = 0
  let notFound = 0

  for (let i = 0; i < ebayIds.length; i++) {
    const ebayId = ebayIds[i]
    const photos = imagesMap[ebayId]
    
    const { error } = await supabase
      .from('products')
      .update({ photos })
      .eq('ebay_id', ebayId)
    
    if (error) {
      notFound++
    } else {
      success++
    }
    
    if ((i + 1) % 100 === 0) {
      process.stdout.write(`\r✓ ${i+1}/${ebayIds.length} mis à jour`)
    }
  }

  console.log(`\n\n✅ Terminé!`)
  console.log(`   ✓ Mis à jour: ${success}`)
  console.log(`   ✗ Non trouvés: ${notFound}`)
}

updateImages().catch(console.error)
